import React, { useState, useEffect } from 'react';
import eventsApi from '../api/eventsApi';
import '../styles/AdminDashboardPage.css';
import EventCard from '../components/EventCard';
import { useLocation, useNavigate } from 'react-router-dom';

const AdminDashboardPage = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    loadAllEvents();
  }, []);

  const loadAllEvents = async () => {
    try {
      setLoading(true);
      const data = await eventsApi.getAllEvents();
      setEvents(data);
      setError('');
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const totalEvents = events.length;
  const openEvents = events.filter(e => e.status === 'OPEN').length;
  const fullEvents = events.filter(e => e.status === 'FULL').length;
  const totalRegistered = events.reduce((sum, e) => sum + e.registered, 0);

  if (loading) return <div className="admin-page"><p>Loading...</p></div>;
  if (error) return <div className="admin-page"><p style={{ color: 'red' }}>{error}</p></div>;

  return (
    <div className="admin-shell">
      <div className="admin-sidebar">
        <div className="admin-logo">
          <h2>Admin Panel</h2>
        </div>
        <nav className="admin-nav">
          <button className={`nav-item ${location.pathname === '/admin' ? 'active' : ''}`} onClick={() => navigate('/admin')}>Dashboard</button>
          <button className="nav-item" onClick={() => navigate('/admin/create-event')}>Create Event</button>
          <button className="nav-item" onClick={() => navigate('/')}>All Events</button>
          <button className="nav-item" onClick={() => navigate('/my-events')}>My Events</button>
        </nav>
      </div>

      <div className="admin-content">
        <div className="admin-header">
          <h1>Event Management Dashboard</h1>
          <p>Review all added events and open details from one place</p>
        </div>

        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-value">{totalEvents}</div>
            <div className="stat-label">Total Events</div>
          </div>
          <div className="stat-card">
            <div className="stat-value">{openEvents}</div>
            <div className="stat-label">Open Events</div>
          </div>
          <div className="stat-card">
            <div className="stat-value">{fullEvents}</div>
            <div className="stat-label">Full Events</div>
          </div>
          <div className="stat-card">
            <div className="stat-value">{totalRegistered}</div>
            <div className="stat-label">Total Registered</div>
          </div>
        </div>

        <div className="events-panel">
          <h2>All Added Events</h2>
          <div className="events-grid">
            {events.length > 0 ? (
              events.map(event => (
                <div key={event.id} className="event-item">
                  <EventCard
                    event={event}
                    onViewDetails={() => navigate(`/events/${event.id}`)}
                    showRegisterButton={false}
                  />
                </div>
              ))
            ) : (
              <p>No events yet.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboardPage;
